<?php require_once __DIR__."/../config/app.php";require_role("Admin LP2M");$d=["year"=>date("Y"),"wave"=>"","start_date"=>"","end_date"=>"","status"=>"Belum Aktif"];$id=(int)($_GET["id"]??0);if($id){$st=$pdo->prepare("SELECT * FROM periods WHERE id=?");$st->execute([$id]);$d=$st->fetch();if(!$d)exit("Data tidak ditemukan.");}if($_SERVER["REQUEST_METHOD"]==="POST"){require_post_csrf();foreach(["year","wave","start_date","end_date","status"] as $k)$d[$k]=post_string($k);if($d["end_date"]<$d["start_date"])exit("Tanggal selesai harus setelah tanggal mulai.");if($id){$pdo->prepare("UPDATE periods SET year=?,wave=?,start_date=?,end_date=?,status=? WHERE id=?")->execute([$d["year"],$d["wave"],$d["start_date"],$d["end_date"],$d["status"],$id]);flash("success","Periode diperbarui.");}else{$pdo->prepare("INSERT INTO periods(year,wave,start_date,end_date,status) VALUES(?,?,?,?,?)")->execute([$d["year"],$d["wave"],$d["start_date"],$d["end_date"],$d["status"]]);flash("success","Periode ditambahkan.");}redirect("index.php");}$pageTitle=$id?"Edit Periode":"Tambah Periode";require __DIR__."/../partials/header.php";?><h3 class="fw-bold"><?=$id?"Edit":"Tambah"?> Periode</h3><form method="post" class="card p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-6"><label>Tahun</label><input class="form-control" name="year" value="<?=e($d["year"])?>" required></div><div class="col-md-6"><label>Gelombang</label><input class="form-control" name="wave" value="<?=e($d["wave"])?>" required></div><div class="col-md-6"><label>Mulai</label><input class="form-control" type="date" name="start_date" value="<?=e($d["start_date"])?>" required></div><div class="col-md-6"><label>Selesai</label><input class="form-control" type="date" name="end_date" value="<?=e($d["end_date"])?>" required></div><div class="col-md-6"><label>Status</label><select class="form-select" name="status"><?php foreach(["Aktif","Selesai","Belum Aktif"] as $s):?><option <?=$d["status"]===$s?"selected":""?>><?=$s?></option><?php endforeach;?></select></div></div><div class="text-end mt-4"><a href="index.php" class="btn btn-light">Batal</a> <button class="btn btn-primary">Simpan</button></div></form><?php require __DIR__."/../partials/footer.php";?>